VAR
    Local_Fault_Latched : BOOL;
    Start_Edge : R_TRIG;
    Starting_Active : BOOL;
    Starting_Timer : TON;
END_VAR

Start_Edge(CLK := Start_Command);
IF Start_Edge.Q THEN
    Starting_Active := TRUE;
END_IF;

Starting_Timer(IN := Starting_Active, PT := T#2S);
IF Starting_Timer.Q THEN
    Starting_Active := FALSE;
END_IF;

IF Fault_Reset THEN
    Local_Fault_Latched := FALSE;
END_IF;

IF (Motor_Current > 51.9) AND NOT Starting_Active AND Motor_Running THEN
    Local_Fault_Latched := TRUE;
    Overload_Alarm := TRUE;
ELSIF NOT Fault_Reset AND Local_Fault_Latched THEN
    Overload_Alarm := TRUE;
ELSE
    Overload_Alarm := FALSE;
END_IF;

IF (Motor_Current > 51.9 * 1.2) AND Motor_Running THEN
    Overload_Timer(IN := TRUE, PT := T#1500MS);
ELSE
    Overload_Timer(IN := FALSE, PT := T#1500MS);
END_IF;

IF Overload_Timer.Q THEN
    Local_Fault_Latched := TRUE;
END_IF;

Motor_Stop := Local_Fault_Latched OR NOT Start_Command;

